<template><el-popover v-if="allowed" placement="bottom-end" :width="330" trigger="click" @show="load"><template #reference><div class="right-menu-item hover-effect notice-bell" aria-label="通知公告"><el-badge :value="unreadCount" :hidden="!unreadCount" :max="99"><el-icon :size="21"><Bell /></el-icon></el-badge></div></template><div class="notice-popover"><strong>通知公告</strong><el-empty v-if="!rows.length" description="暂无公告" :image-size="55" /><button v-for="row in rows" :key="row.noticeId" class="notice-item" @click="open(row)"><span>{{row.noticeTitle}}</span><small>{{row.isRead?'已读':'未读'}} · {{row.createTime}}</small></button><el-button link type="primary" @click="router.push('/messages')">查看全部公告</el-button></div></el-popover></template>
<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {useRouter} from 'vue-router';import {Bell} from '@element-plus/icons-vue';import useUserStore from '@/store/modules/user';import {listNotices} from '@/api/operations';
const user=useUserStore(),router=useRouter(),rows=ref([]),unreadCount=ref(0),allowed=computed(()=>!!user.roles.length&&!user.demoOnly&&!user.mustChangePassword&&['ADMIN','ENGINEER'].includes(user.accountTier));let timer,loading=false
async function load(){if(!allowed.value||loading)return;loading=true;try{const r=await listNotices({pageNum:1,pageSize:5});rows.value=r.rows;unreadCount.value=r.unreadCount}catch{}finally{loading=false}}
function open(row){router.push({path:'/messages',query:{noticeId:row.noticeId}})}
watch(allowed,v=>{window.clearInterval(timer);if(v){load();timer=window.setInterval(()=>{if(!document.hidden)load()},60000)}else{rows.value=[];unreadCount.value=0}},{immediate:true})
onMounted(()=>window.addEventListener('drilling-notice-read',load));onBeforeUnmount(()=>{window.clearInterval(timer);window.removeEventListener('drilling-notice-read',load)})
</script>
<style scoped>.notice-bell{cursor:pointer;display:inline-flex!important;align-items:center;}.notice-item{display:block;width:100%;text-align:left;padding:12px 0;border:0;border-bottom:1px solid var(--el-border-color-lighter);background:transparent;color:var(--el-text-color-primary);cursor:pointer;}.notice-item span{display:block;overflow-wrap:anywhere;}.notice-item small{display:block;color:var(--el-text-color-secondary);margin-top:6px;}.notice-popover>.el-button{margin-top:14px;}</style>
